function unitPluralForm(aLength, aUnit, aIncludeLength = true) {
  const unitProp =
    {
      minutes: "unit-minutes",
      hours: "unit-hours",
      days: "unit-days",
      weeks: "unit-weeks",
    }[aUnit] || "unit-minutes";
  const unitString = lazy.l10n.formatValueSync(unitProp, { count: aLength });
  if (aIncludeLength) {
    return unitString;
  }
  return unitString.replace(aLength, "").trim();
}

